def _normalized_string_list(
    value: Any,
    *,
    field: str,
    minimum: int,
    maximum: int,
) -> list[str]:
    if not isinstance(value, list):
        raise ValueError(f"research +creative-search-ads requires --keyword ({field}).")
    if any(not isinstance(item, str) for item in value):
        raise ValueError(f"{field} values must be strings.")
    normalized = [item.strip() for item in value if item.strip()]
    if len(normalized) < minimum:
        raise ValueError(f"{field} requires at least {minimum} value.")
    if len(normalized) > maximum:
        raise ValueError(f"{field} accepts at most {maximum} values.")
    if any(len(item) > 200 for item in normalized):
        raise ValueError(f"{field} values must be at most 200 characters.")
    if len(normalized) != len(set(normalized)):
        raise ValueError(f"{field} values must be unique.")
    return normalized


def _normalized_choice_list(
    value: Any,
    *,
    field: str,
    choices: list[str],
    default: list[str],
) -> list[str]:
    raw = default if value is None else value
    if not isinstance(raw, list):
        raise ValueError(f"{field} must be an array.")
    normalized = [dekebab(str(item)) for item in raw]
    invalid = [item for item in normalized if item not in choices]
    if invalid:
        raise ValueError(f"{field} contains unsupported values: {', '.join(invalid)}.")
    if not normalized:
        raise ValueError(f"{field} requires at least one value.")
    if len(normalized) != len(set(normalized)):
        raise ValueError(f"{field} values must be unique.")
    return normalized


def _add_visual_analyze_arguments(parser: argparse.ArgumentParser) -> None:
    _add_common_adapter_arguments(parser)
    parser.add_argument(
        "--media",
        action="append",
        dest="media_urls",
        help=(
            "Image/video URL to analyze. For TikTok or signed CDN URLs that fail "
            "direct preparation, first run `asset +create --type media --url ...` "
            "and retry with the returned media_url or permanent_media_url."
        ),
    )
    parser.add_argument("--media-json")
    parser.add_argument("--media-file")
    parser.add_argument("--prompt", required=True)
    parser.add_argument("--context")


def _build_visual_analyze_arguments(args: argparse.Namespace) -> dict[str, Any]:
    payload = _load_structured_args(args)
    _reject_server_controlled_fields(
        payload,
        fields={"model", "temperature", "max_output_tokens"},
        context="research +visual-analyze",
    )
    if args.media_json:
        payload["media"] = _json_list(args.media_json, flag="--media-json")
    if args.media_file:
        media_payload = Path(args.media_file).read_text(encoding="utf-8")
        payload["media"] = _json_list(media_payload, flag="--media-file")
    if args.media_urls:
        payload["media"] = list(args.media_urls)
    if not payload.get("media"):
        raise ValueError(
            "research +visual-analyze requires --media, --media-json, or --media-file."
        )
    payload["prompt"] = args.prompt
    if args.context is not None:
        payload["context"] = args.context
    return payload


