def _community_search_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "platform": {
                "type": "string",
                "enum": COMMUNITY_PLATFORM_CHOICES,
                "description": "Community platform to search: x, reddit, or linkedin.",
            },
            "intent": {
                "type": "string",
                "enum": kebab_choices(COMMUNITY_INTENT_CHOICES),
                "description": (
                    "Domain search intent. Use keyword_search for discovery, "
                    "profile/company_profile for entity hydration, "
                    "creator_posts/community_posts/company_posts for timelines, "
                    "post for one item, comments for discussion, and trending for topical discovery."
                ),
            },
            "query": {
                "type": "string",
                "minLength": 1,
                "maxLength": 4096,
                "description": (
                    "Search keyword, LinkedIn company slug, or LinkedIn company URL "
                    "depending on platform and intent. For post/comments, pass the "
                    "platform post URL or ID."
                ),
            },
            "limit": {"type": "integer", "minimum": 1, "maximum": 30, "default": 5},
            "content_chars": {
                "type": "integer",
                "minimum": 0,
                "maximum": 4000,
                "default": 800,
            },
            "region": {"type": "string", "minLength": 2, "maxLength": 2, "default": "US"},
            "timeout": {"type": "integer", "minimum": 5, "maximum": 120, "default": 10},
            "max_retries": {"type": "integer", "minimum": 0, "maximum": 3, "default": 3},
            "sort": {"type": "string", "enum": SEARCH_SORT_CHOICES, "default": "relevance"},
            "time_window": {
                "type": "string",
                "enum": kebab_choices(SEARCH_TIME_WINDOW_CHOICES),
                "default": "any",
            },
            "cursor": {
                "type": ["string", "null"],
                "description": (
                    "Optional pagination cursor from evidence.pagination. "
                    "For LinkedIn search this may be a page/start number; for X and Reddit "
                    "it is the cursor/after token."
                ),
            },
            "search_type": {
                "type": ["string", "null"],
                "description": (
                    "Optional Reddit keyword search category: post, community, comment, "
                    "media, or people. Ignored by X and LinkedIn."
                ),
            },
            "allow_slow": {
                "type": "boolean",
                "default": False,
                "description": (
                    "Backward-compatible no-op kept so older CLI invocations do not break."
                ),
            },
        },
        "required": ["platform", "intent", "query"],
    }


def _creative_search_ads_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "idempotency_key": {
                "type": "string",
                "minLength": 1,
                "maxLength": 240,
                "description": (
                    "Caller-stable key reused only when retrying the same Ads search intent."
                ),
            },
            "keywords": {
                "type": "array",
                "minItems": 1,
                "maxItems": 10,
                "uniqueItems": True,
                "items": {"type": "string", "minLength": 1, "maxLength": 200},
                "description": "One to ten Ads search keywords.",
            },
            "ad_platforms": {
                "type": "array",
                "minItems": 1,
                "maxItems": 2,
                "uniqueItems": True,
                "items": {
                    "type": "string",
                    "enum": kebab_choices(CREATIVE_SEARCH_ADS_PLATFORM_CHOICES),
                },
                "default": kebab_choices(CREATIVE_SEARCH_ADS_PLATFORM_CHOICES),
                "description": "Ad libraries to search.",
            },
            "media_types": {
                "type": "array",
                "minItems": 1,
                "maxItems": 2,
                "uniqueItems": True,
                "items": {
                    "type": "string",
                    "enum": CREATIVE_SEARCH_ADS_MEDIA_TYPE_CHOICES,
                },
                "default": ["video"],
            },
            "limit_per_platform": {
                "type": "integer",
                "minimum": 1,
                "maximum": 100,
                "default": 20,
                "description": "Maximum results per keyword and ad library.",
            },
        },
        "required": ["idempotency_key", "keywords"],
    }


def _creative_search_ads_get_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "task_id": _uuid_id_schema("Creative Search Ads task UUID."),
        },
        "required": ["task_id"],
    }


def _creative_search_ads_results_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "task_id": _uuid_id_schema("Creative Search Ads task UUID."),
            "platform": {
                "type": ["string", "null"],
                "enum": [*kebab_choices(CREATIVE_SEARCH_ADS_PLATFORM_CHOICES), None],
            },
            "time_range": {
                "type": "string",
                "enum": CREATIVE_SEARCH_ADS_TIME_RANGE_CHOICES,
                "default": "all",
            },
            "page": {"type": "integer", "minimum": 1, "default": 1},
            "page_size": {
                "type": "integer",
                "minimum": 1,
                "maximum": 100,
                "default": 20,
            },
            "sort_by": {
                "type": "string",
                "enum": kebab_choices(CREATIVE_SEARCH_ADS_SORT_CHOICES),
                "default": "published-at",
            },
        },
        "required": ["task_id"],
    }


def _visual_analyze_input_schema() -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "media": {
                "type": "array",
                "minItems": 1,
                "maxItems": 12,
                "items": {
                    "anyOf": [
                        {"type": "string"},
                        {
                            "type": "object",
                            "properties": {
                                "url": {"type": "string"},
                                "type": {
                                    "type": ["string", "null"],
                                    "enum": ["image", "video", None],
                                },
                                "mime_type": {"type": ["string", "null"]},
                                "label": {"type": ["string", "null"]},
                            },
                            "required": ["url"],
                        },
                    ]
                },
            },
            "prompt": {"type": "string", "minLength": 1, "maxLength": 12000},
            "context": {"type": ["string", "null"], "maxLength": 4000},
        },
        "required": ["media", "prompt"],
    }


